precision highp float;
uniform vec2 resolution;
out vec4 outputColor;
float boxDistance(vec3 p,vec3 extent){vec3 q=abs(p)-extent;return length(max(q,0.0))+min(max(q.x,max(q.y,q.z)),0.0);}
