d=length(p-vec3(-2.00000000e+0,0.00000000e+0,0.00000000e+0))-4.49999988e-1; if(d<nearest){nearest=d; material=vec3(2.58823544e-1,7.84313738e-1,8.35294127e-1);}
d=length(p-vec3(2.00000000e+0,0.00000000e+0,0.00000000e+0))-4.49999988e-1; if(d<nearest){nearest=d; material=vec3(2.58823544e-1,7.84313738e-1,8.35294127e-1);}
d=length(p-vec3(0.00000000e+0,1.50000000e+0,0.00000000e+0))-4.49999988e-1; if(d<nearest){nearest=d; material=vec3(9.64705884e-1,7.68627465e-1,3.25490206e-1);}return nearest;}
